#!/usr/bin/env bash
# ============================================================================
#  Epson Scan 2 (6.7.93.0-1) â€” Ù†ØµØ¨â€ŒÚ©Ù†Ù†Ø¯Ù‡ Ø®ÙˆØ¯Ú©Ø§Ø± Ø¨Ø±Ø§ÛŒ Raspberry Pi 5 / Ubuntu (arm64)
#  Easy installer: builds Epson Scan 2 from the bundled source and installs it
#  as a proper .deb package (removable with:  sudo apt remove epsonscan2)
#
#  Usage:   bash install-epsonscan2-rpi5.sh
#  Options: --keep-build   keep the build directory
#           --no-install   only build the .deb, do not install it
# ============================================================================
set -Eeuo pipefail

EPS_VER="6.7.93.0"
EPS_REV="1"
KEEP_BUILD=0
DO_INSTALL=1
for a in "$@"; do
  case "$a" in
    --keep-build) KEEP_BUILD=1 ;;
    --no-install) DO_INSTALL=0 ;;
    -h|--help) sed -n 2,12p "$0"; exit 0 ;;
    *) echo "Unknown option: $a" >&2; exit 2 ;;
  esac
done

c_info()  { printf '\033[1;34m[*]\033[0m %s\n' "$*"; }
c_ok()    { printf '\033[1;32m[âœ“]\033[0m %s\n' "$*"; }
c_warn()  { printf '\033[1;33m[!]\033[0m %s\n' "$*"; }
c_err()   { printf '\033[1;31m[âœ—]\033[0m %s\n' "$*" >&2; }
trap 'c_err "Failed at line $LINENO. Re-run with: bash -x $0  to debug."' ERR

# ---- privileges: build as the normal user, use sudo only where required ----
if [ "$(id -u)" -eq 0 ]; then
  SUDO=""
  c_warn "Running as root; the build will run as root (works, but a normal user + sudo is preferred)."
else
  command -v sudo >/dev/null || { c_err "sudo is required."; exit 1; }
  SUDO="sudo"
  c_info "Requesting sudo (needed for apt / dpkg)â€¦"
  sudo -v
fi

# ---- environment checks ----
ARCH="$(dpkg --print-architecture)"
MULTIARCH="$(dpkg-architecture -qDEB_HOST_MULTIARCH 2>/dev/null || gcc -dumpmachine)"
OS_NAME="$(. /etc/os-release; echo "${PRETTY_NAME:-unknown}")"
c_info "System: ${OS_NAME} / ${ARCH} (${MULTIARCH})"
[ "$ARCH" = "arm64" ] || c_warn "This installer targets arm64 (Raspberry Pi 5); detected '$ARCH'. Continuing anyway."
if [ -r /proc/device-tree/model ]; then c_info "Board: $(tr -d '\0' </proc/device-tree/model)"; fi

# ---- 1) dependencies ----
c_info "Installing build/runtime dependencies (this can take a few minutes)â€¦"
$SUDO apt-get update
DEPS=(build-essential cmake pkg-config ca-certificates openssl sane-utils
      libboost-dev libboost-filesystem-dev
      libjpeg-dev libtiff-dev libpng-dev zlib1g-dev
      rapidjson-dev libusb-1.0-0-dev libsane-dev
      qtbase5-dev)
$SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y "${DEPS[@]}"
c_ok "Dependencies installed."

# ---- 2) unpack the bundled source ----
WORK="${XDG_CACHE_HOME:-$HOME/.cache}/epsonscan2-build"
mkdir -p "$WORK"
BUILD_OK=0
cleanup() {
  if [ "$BUILD_OK" -eq 1 ] && [ "$KEEP_BUILD" -eq 0 ]; then rm -rf "$WORK"
  else c_info "Build dir kept for a faster re-run: $WORK"; fi
}
trap cleanup EXIT

SRC="$WORK/epsonscan2-${EPS_VER}-${EPS_REV}"
SELF="$(readlink -f "$0")"
# remove leftovers from earlier script versions (they used a different dir name / flags)
for d in "$WORK"/epsonscan2-*; do [ -e "$d" ] && [ "$d" != "$SRC" ] && rm -rf "$d" "$WORK/_build" || true; done
extract_source() {
  local line sib
  rm -rf "$SRC"
  # (a) archive embedded in this script
  line="$(grep -a -n -m1 '^__ARCHIVE_BELOW__[[:space:]]*$' "$SELF" | cut -d: -f1 || true)"
  if [ -n "$line" ] && tail -n +"$((line + 1))" "$SELF" | tar -xz -C "$WORK" 2>"$WORK/tar.err"; then
    [ -d "$SRC" ] && return 0
  fi
  c_warn "Embedded source could not be extracted ($(head -n1 "$WORK/tar.err" 2>/dev/null || echo 'marker not found'))."
  # (b) fall back to the original tarball placed next to this script or in the current dir
  for sib in "$(dirname "$SELF")"/*epsonscan2-*.src.tar.gz "$PWD"/*epsonscan2-*.src.tar.gz; do
    if [ -f "$sib" ]; then
      c_info "Trying $sib"
      if tar -xzf "$sib" -C "$WORK"; then
        [ -d "$SRC" ] && return 0
        # tarball with a different top-level dir name: normalise it
        local top; top="$(tar -tzf "$sib" | head -n1 | cut -d/ -f1)"
        [ -n "$top" ] && [ -d "$WORK/$top" ] && mv "$WORK/$top" "$SRC" && return 0
      fi
    fi
  done
  return 1
}
if [ -d "$SRC" ]; then
  c_info "Reusing existing source/build tree in $WORK (incremental build)."
else
  c_info "Extracting source to $WORK â€¦"
  if ! extract_source; then
    c_err "Source extraction failed. Script size: $(stat -c %s "$SELF") bytes (expected ~2.97 MB)."
    c_err "The file was probably damaged in transfer. Copy the script again (binary mode, e.g. scp) or put the"
    c_err "original epsonscan2-*.src.tar.gz in the same folder as this script and re-run."
    ls -la "$WORK" >&2 || true
    exit 1
  fi
fi
[ -d "$SRC" ] || { c_err "Source tree missing."; exit 1; }

# ---- 3) compatibility patches for modern toolchains (GCC 14/15, CMake 4, new Boost) ----
c_info "Applying compatibility patchesâ€¦"
# the code base is C++11-era; gnu++14 is the safest dialect for new GCC + Boost
patch_sed() {  # patch_sed <grep-regex> <sed-expr> <find-name-glob>...
  local re="$1" expr="$2"; shift 2
  local g n=()
  for g in "$@"; do n+=(-o -name "$g"); done
  find "$SRC" -type f \( -false "${n[@]}" \) -print0 \
    | xargs -0 grep -lZ -- "$re" 2>/dev/null | xargs -0 -r sed -i "$expr" || true
}
# the code base is C++11-era; gnu++14 is the safest dialect for new GCC + Boost
patch_sed '-std=c++11' 's/-std=c++11/-std=gnu++14/g' CMakeLists.txt
# Boost >= 1.87 refuses to build when this legacy macro is defined (Boost.Optional #error).
# It is defined both in CMake files and directly inside source/header files.
patch_sed 'BOOST_NO_CXX11_RVALUE_REFERENCES' '/BOOST_NO_CXX11_RVALUE_REFERENCES/d' CMakeLists.txt '*.h' '*.hpp' '*.cpp'
patch_sed '/tmp/build' 's#/tmp/build#${CMAKE_BINARY_DIR}/out#g' CMakeLists.txt
# make the "home" settings path not depend on who runs cmake
unset EPSON_VERSION BUILD_TYPE || true

# ---- 4) configure + build ----
BUILD="$WORK/_build"; STAGE="$WORK/_stage"; rm -rf "$STAGE"; mkdir -p "$BUILD" "$STAGE"

MEM_KB="$(awk '/MemTotal/ {print $2}' /proc/meminfo)"
JOBS="$(nproc)"
MAXJ=$(( MEM_KB / 1500000 )); [ "$MAXJ" -lt 1 ] && MAXJ=1
[ "$JOBS" -gt "$MAXJ" ] && JOBS="$MAXJ"
JOBS="${EPS_JOBS:-$JOBS}"   # override: EPS_JOBS=4 bash install-epsonscan2.sh
c_info "Building with $JOBS parallel job(s) (RAM: $((MEM_KB/1024)) MB). On a Pi 5 this takes ~5â€“15 minutes."

# The bundled gcc flags: -fpermissive downgrades old-code errors to warnings.
CXXF="-fsigned-char -fno-strict-aliasing -fpermissive -Wno-error -Wno-deprecated-declarations -include cstdint -include cstring"
CF="-fsigned-char -fno-strict-aliasing -Wno-error -Wno-implicit-function-declaration -Wno-int-conversion -Wno-incompatible-pointer-types"
cmake -S "$SRC" -B "$BUILD" \
  -DCMAKE_BUILD_TYPE=Release \
  -DCMAKE_POLICY_VERSION_MINIMUM=3.5 \
  -DCMAKE_CXX_FLAGS="$CXXF" -DCMAKE_C_FLAGS="$CF" \
  -DEPSON_INSTALL_ROOT="$STAGE" \
  -DEPSON_OCR_INSTALL_PATH="/usr/lib/${MULTIARCH}/epsonscan2-ocr/" \
  -DEPSON_VERSION="-${EPS_VER}-${EPS_REV}" \
  -Wno-dev
BUILD_LOG="$WORK/build.log"
if ! cmake --build "$BUILD" -j"$JOBS" >"$BUILD_LOG" 2>&1; then
  c_warn "Parallel build failed; re-running single-threaded to isolate the errorâ€¦"
  if ! cmake --build "$BUILD" -j1 >"$BUILD_LOG" 2>&1; then
    c_err "Build failed. First errors:"
    grep -n -B4 -A8 -E 'error|Error [0-9]|undefined reference|cannot find' "$BUILD_LOG" | head -80 >&2 || tail -n 40 "$BUILD_LOG" >&2
    c_err "Full log: $BUILD_LOG   â€” send the lines above (or: grep -n -B4 -A8 error $BUILD_LOG | head -80)"
    exit 1
  fi
fi
tail -n 3 "$BUILD_LOG"
c_ok "Build finished."

# ---- 5) stage files ----
c_info "Staging filesâ€¦"
cmake --install "$BUILD" >/dev/null

LIBDIR="$STAGE/usr/lib/${MULTIARCH}/epsonscan2"
[ -x "$STAGE/usr/bin/epsonscan2" ] || { c_err "/usr/bin/epsonscan2 was not produced."; exit 1; }
[ -d "$LIBDIR" ] || { c_err "Library dir $LIBDIR missing (unexpected install layout)."; find "$STAGE" -maxdepth 4 | head -40; exit 1; }
[ -e "$LIBDIR/libsane-epsonscan2.so" ] || c_warn "libsane-epsonscan2.so not found in staging dir."

# desktop entry (the one in the source tree hard-codes x86_64 paths)
install -d "$STAGE/usr/share/applications"
cat > "$STAGE/usr/share/applications/epsonscan2.desktop" <<DESK
[Desktop Entry]
Type=Application
Name=Epson Scan 2
GenericName=Scanner
Comment=Scan with Epson scanners
Exec=/usr/bin/epsonscan2
Terminal=false
StartupNotify=true
Icon=/usr/lib/${MULTIARCH}/epsonscan2/Resources/Icons/escan2_app.png
Categories=Graphics;Scanning;RasterGraphics;
DESK

# ---- 6) build the .deb ----
c_info "Creating .deb packageâ€¦"
PKG="$STAGE"
install -d "$PKG/DEBIAN"
INSTALLED_SIZE="$(du -sk "$STAGE" | cut -f1)"
cat > "$PKG/DEBIAN/control" <<CTL
Package: epsonscan2
Version: ${EPS_VER}-${EPS_REV}
Architecture: ${ARCH}
Maintainer: Local Build <root@localhost>
Installed-Size: ${INSTALLED_SIZE}
Section: graphics
Priority: optional
Depends: sane-utils, openssl, libusb-1.0-0, libtiff6 | libtiff5, libjpeg-turbo8 | libjpeg8, libpng16-16t64 | libpng16-16, libqt5widgets5t64 | libqt5widgets5, libqt5gui5t64 | libqt5gui5, libqt5core5t64 | libqt5core5a
Description: Epson Scan 2 scanner driver and GUI (built from source for ${ARCH})
 Epson Scan 2 - Simple Image Acquisition. Native driver for many EPSON
 scanners plus a SANE backend (libsane-epsonscan2).
 For network scanning install Epson's separate "epsonscan2-non-free-plugin".
CTL
cat > "$PKG/DEBIAN/postinst" <<'PI'
#!/bin/sh
set -e
if command -v udevadm >/dev/null 2>&1; then
  udevadm control --reload-rules || true
  udevadm trigger --subsystem-match=usb --action=add || true
fi
command -v update-desktop-database >/dev/null 2>&1 && update-desktop-database -q || true
exit 0
PI
cat > "$PKG/DEBIAN/postrm" <<'PR'
#!/bin/sh
set -e
if command -v udevadm >/dev/null 2>&1; then udevadm control --reload-rules || true; fi
exit 0
PR
chmod 0755 "$PKG/DEBIAN/postinst" "$PKG/DEBIAN/postrm"
find "$PKG" -type d -exec chmod 0755 {} +

DEB_NAME="epsonscan2_${EPS_VER}-${EPS_REV}_${ARCH}.deb"
dpkg-deb --root-owner-group --build "$PKG" "$WORK/$DEB_NAME" >/dev/null
OUT_DIR="$(pwd)"
cp -f "$WORK/$DEB_NAME" "$OUT_DIR/$DEB_NAME"
c_ok "Package created: $OUT_DIR/$DEB_NAME"
BUILD_OK=1

# ---- 7) install ----
if [ "$DO_INSTALL" -eq 1 ]; then
  c_info "Installing packageâ€¦"
  $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y "$OUT_DIR/$DEB_NAME"
  c_ok "Epson Scan 2 installed."
  echo
  echo "  Run the app:     epsonscan2"
  echo "  List scanners:   scanimage -L   (SANE backend: epsonscan2)"
  echo "  USB scanners:    unplug & re-plug the scanner once (udev rules were loaded)."
  echo "  Uninstall:       sudo apt remove epsonscan2"
else
  c_info "Skipped installation (--no-install). Install later with: sudo apt install ./$DEB_NAME"
fi
exit 0
__ARCHIVE_BELOW__
